119	// bindData will bind data ONLY fields in destination struct that have EXPLICIT tag
120	func (b *DefaultBinder) bindData(destination interface{}, data map[string][]string, tag string) error {
121		if destination == nil || len(data) == 0 {
122			return nil
123		}
124		typ := reflect.TypeOf(destination).Elem()
125		val := reflect.ValueOf(destination).Elem()
126	
127		// Map
128		if typ.Kind() == reflect.Map {
129			for k, v := range data {
130				val.SetMapIndex(reflect.ValueOf(k), reflect.ValueOf(v[0]))
131			}
132			return nil
133		}
134	
135		// !struct
136		if typ.Kind() != reflect.Struct {
137			return errors.New("binding element must be a struct")
138		}
139	
140		for i := 0; i < typ.NumField(); i++ {
141			typeField := typ.Field(i)
142			structField := val.Field(i)
143			if !structField.CanSet() {
144				continue
145			}
146			structFieldKind := structField.Kind()
147			inputFieldName := typeField.Tag.Get(tag)
148	
149			if inputFieldName == "" {
150				// If tag is nil, we inspect if the field is a not BindUnmarshaler struct and try to bind data into it (might contains fields with tags).
151				// structs that implement BindUnmarshaler are binded only when they have explicit tag
152				if _, ok := structField.Addr().Interface().(BindUnmarshaler); !ok && structFieldKind == reflect.Struct {
153					if err := b.bindData(structField.Addr().Interface(), data, tag); err != nil {
154						return err
155					}
156				}
157				// does not have explicit tag and is not an ordinary struct - so move to next field
158				continue
159			}
160	
161			inputValue, exists := data[inputFieldName]
162			if !exists {
163				// Go json.Unmarshal supports case insensitive binding.  However the
164				// url params are bound case sensitive which is inconsistent.  To
165				// fix this we must check all of the map values in a
166				// case-insensitive search.
167				for k, v := range data {
168					if strings.EqualFold(k, inputFieldName) {
169						inputValue = v
170						exists = true
171						break
172					}
173				}
174			}
175	
176			if !exists {
177				continue
178			}
179	
180			// Call this first, in case we're dealing with an alias to an array type
181			if ok, err := unmarshalField(typeField.Type.Kind(), inputValue[0], structField); ok {
182				if err != nil {
183					return err
184				}
185				continue
186			}
187	
188			numElems := len(inputValue)
189			if structFieldKind == reflect.Slice && numElems > 0 {
190				sliceOf := structField.Type().Elem().Kind()
191				slice := reflect.MakeSlice(structField.Type(), numElems, numElems)
192				for j := 0; j < numElems; j++ {
193					if err := setWithProperType(sliceOf, inputValue[j], slice.Index(j)); err != nil {
194						return err
195					}
196				}
197				val.Field(i).Set(slice)
198			} else if err := setWithProperType(typeField.Type.Kind(), inputValue[0], structField); err != nil {
199				return err
200	
201			}
202		}
203		return nil
204	}
205	
206	func setWithProperType(valueKind reflect.Kind, val string, structField reflect.Value) error {
207		// But also call it here, in case we're dealing with an array of BindUnmarshalers
208		if ok, err := unmarshalField(valueKind, val, structField); ok {
209			return err
210		}
211	
212		switch valueKind {
213		case reflect.Ptr:
214			return setWithProperType(structField.Elem().Kind(), val, structField.Elem())
215		case reflect.Int:
216			return setIntField(val, 0, structField)
217		case reflect.Int8:
218			return setIntField(val, 8, structField)
219		case reflect.Int16:
220			return setIntField(val, 16, structField)
221		case reflect.Int32:
222			return setIntField(val, 32, structField)
223		case reflect.Int64:
224			return setIntField(val, 64, structField)
225		case reflect.Uint:
226			return setUintField(val, 0, structField)
227		case reflect.Uint8:
228			return setUintField(val, 8, structField)
229		case reflect.Uint16:
230			return setUintField(val, 16, structField)
231		case reflect.Uint32:
232			return setUintField(val, 32, structField)
233		case reflect.Uint64:
234			return setUintField(val, 64, structField)
235		case reflect.Bool:
236			return setBoolField(val, structField)
237		case reflect.Float32:
238			return setFloatField(val, 32, structField)
239		case reflect.Float64:
240			return setFloatField(val, 64, structField)
241		case reflect.String:
242			structField.SetString(val)
243		default:
244			return errors.New("unknown type")
245		}
246		return nil
247	}
248	
249	func unmarshalField(valueKind reflect.Kind, val string, field reflect.Value) (bool, error) {
250		switch valueKind {
251		case reflect.Ptr:
252			return unmarshalFieldPtr(val, field)
253		default:
254			return unmarshalFieldNonPtr(val, field)
255		}
256	}
257	
258	func unmarshalFieldNonPtr(value string, field reflect.Value) (bool, error) {
259		fieldIValue := field.Addr().Interface()
260		if unmarshaler, ok := fieldIValue.(BindUnmarshaler); ok {
261			return true, unmarshaler.UnmarshalParam(value)
262		}
263		if unmarshaler, ok := fieldIValue.(encoding.TextUnmarshaler); ok {
264			return true, unmarshaler.UnmarshalText([]byte(value))
265		}
266	
267		return false, nil
268	}
269	
270	func unmarshalFieldPtr(value string, field reflect.Value) (bool, error) {
271		if field.IsNil() {
272			// Initialize the pointer to a nil value
273			field.Set(reflect.New(field.Type().Elem()))
274		}
275		return unmarshalFieldNonPtr(value, field.Elem())
276	}
