func TestScratchEmptyStringGzip(t *testing.T) {
	e := echo.New()
	e.Use(Gzip())
	e.GET("/empty", func(c echo.Context) error {
		return c.String(http.StatusOK, "")
	})
	req := httptest.NewRequest(http.MethodGet, "/empty", nil)
	req.Header.Set(echo.HeaderAcceptEncoding, gzipScheme)
	rec := httptest.NewRecorder()
	e.ServeHTTP(rec, req)

	body := rec.Body.Bytes()
	t.Logf("status=%d CE=%q CT=%q len=%d body=%q", rec.Code, rec.Header().Get(echo.HeaderContentEncoding), rec.Header().Get(echo.HeaderContentType), len(body), body)
	if len(body) >= 2 && body[0] == 0x1f && body[1] == 0x8b {
		if rec.Header().Get(echo.HeaderContentEncoding) != gzipScheme {
			t.Errorf("BUG: gzip magic bytes in body but no Content-Encoding header")
		}
	}
	// also check via a real client-ish path
	if rec.Header().Get(echo.HeaderContentEncoding) == gzipScheme {
		r, err := gzip.NewReader(bytes.NewReader(body))
		if err != nil {
			t.Fatalf("Content-Encoding gzip but body not valid gzip: %v", err)
		}
		buf := new(bytes.Buffer)
		buf.ReadFrom(r)
		r.Close()
		t.Logf("decompressed=%q", buf.String())
		if buf.String() != "" {
			t.Errorf("expected empty decompressed body, got %q", buf.String())
		}
	}
}
