	g1 := e.Group("/group", m1)
	g1.GET("", h)
	g2 := e.Group("/group", m2)
	g2.GET("/other", h)

	for _, p := range []string{"/group", "/group/other"} {
		req := httptest.NewRequest(http.MethodGet, p, nil)
		rec := httptest.NewRecorder()
		e.ServeHTTP(rec, req)
		t.Logf("path=%s status=%d body=%q hdrM1=%q hdrM2=%q", p, rec.Code, rec.Body.String(), rec.Header().Get("X-M1"), rec.Header().Get("X-M2"))
		if rec.Code != http.StatusOK {
			t.Errorf("path %s: expected 200 got %d", p, rec.Code)
		}
	}
}
