package echo

import (
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

type scratchMapKey string
type scratchStringSlice []string
type scratchString string

func TestScratchBindToMap(t *testing.T) {
	e := New()
	req := httptest.NewRequest(http.MethodGet, "/?tag=a&tag=b&id=1&name=Jon+Snow", nil)
	rec := httptest.NewRecorder()
	c := e.NewContext(req, rec)

	// map[string][]string: all values per key
	m := map[string][]string{}
	if err := c.Bind(&m); err != nil {
		t.Fatalf("map[string][]string bind error: %v", err)
	}
	if len(m) != 3 || len(m["tag"]) != 2 || m["tag"][0] != "a" || m["tag"][1] != "b" {
		t.Fatalf("map[string][]string = %#v, want tag=[a b] id=[1] name=[Jon Snow]", m)
	}
	if len(m["id"]) != 1 || m["id"][0] != "1" || len(m["name"]) != 1 || m["name"][0] != "Jon Snow" {
		t.Fatalf("map[string][]string single values wrong: %#v", m)
	}

	// map[string]string: first value only (pre-existing behavior)
	m2 := map[string]string{}
	if err := c.Bind(&m2); err != nil {
		t.Fatalf("map[string]string bind error: %v", err)
	}
	if m2["tag"] != "a" || m2["id"] != "1" || m2["name"] != "Jon Snow" {
		t.Fatalf("map[string]string = %#v", m2)
	}

	// map[string]interface{}: single string per key (pre-existing behavior)
	m3 := map[string]interface{}{}
	if err := c.Bind(&m3); err != nil {
		t.Fatalf("map[string]interface{} bind error: %v", err)
	}
	if m3["tag"] != "a" || m3["id"] != "1" || m3["name"] != "Jon Snow" {
		t.Fatalf("map[string]interface{} = %#v", m3)
	}

	// nil maps are initialized instead of panicking
	var m4 map[string][]string
	if err := c.Bind(&m4); err != nil {
		t.Fatalf("nil map[string][]string bind error: %v", err)
	}
	if len(m4["tag"]) != 2 || m4["tag"][0] != "a" || m4["tag"][1] != "b" {
		t.Fatalf("nil map[string][]string = %#v", m4)
	}
	var m5 map[string]string
	if err := c.Bind(&m5); err != nil {
		t.Fatalf("nil map[string]string bind error: %v", err)
	}
	if m5["id"] != "1" {
		t.Fatalf("nil map[string]string = %#v", m5)
	}

	// unsupported map element types are ignored, not panicking
	m6 := map[string]int{}
	if err := c.Bind(&m6); err != nil {
		t.Fatalf("map[string]int bind error: %v", err)
	}
	if len(m6) != 0 {
		t.Fatalf("map[string]int = %#v, want empty", m6)
	}

	// named string key/element types do not panic
	m7 := map[scratchMapKey]scratchStringSlice{}
	if err := c.Bind(&m7); err != nil {
		t.Fatalf("named map[string][]string bind error: %v", err)
	}
	if len(m7["tag"]) != 2 || m7["tag"][0] != "a" {
		t.Fatalf("named map = %#v", m7)
	}
	m8 := map[scratchMapKey]scratchString{}
	if err := c.Bind(&m8); err != nil {
		t.Fatalf("named map[string]string bind error: %v", err)
	}
	if m8["id"] != "1" {
		t.Fatalf("named map[string]string = %#v", m8)
	}

	// form binding uses the same code path
	req2 := httptest.NewRequest(http.MethodPost, "/", strings.NewReader("tag=a&tag=b&id=1"))
	req2.Header.Set(HeaderContentType, MIMEApplicationForm)
	c2 := e.NewContext(req2, httptest.NewRecorder())
	m9 := map[string][]string{}
	if err := c2.Bind(&m9); err != nil {
		t.Fatalf("form map[string][]string bind error: %v", err)
	}
	if len(m9["tag"]) != 2 || m9["tag"][0] != "a" || m9["tag"][1] != "b" {
		t.Fatalf("form map[string][]string = %#v", m9)
	}

	// path params binding
	req3 := httptest.NewRequest(http.MethodGet, "/", nil)
	c3 := e.NewContext(req3, httptest.NewRecorder())
	c3.SetParamNames("id")
	c3.SetParamValues("999")
	m10 := map[string][]string{}
	if err := c3.BindPathParams(&m10); err != nil {
		t.Fatalf("path map[string][]string bind error: %v", err)
	}
	if len(m10["id"]) != 1 || m10["id"][0] != "999" {
		t.Fatalf("path map[string][]string = %#v", m10)
	}

	// struct binding with slices must keep working
	req4 := httptest.NewRequest(http.MethodGet, "/?tag=a&tag=b", nil)
	c4 := e.NewContext(req4, httptest.NewRecorder())
	dest := struct {
		Tag []string `query:"tag"`
	}{}
	if err := c4.Bind(&dest); err != nil {
		t.Fatalf("struct bind error: %v", err)
	}
	if len(dest.Tag) != 2 || dest.Tag[0] != "a" || dest.Tag[1] != "b" {
		t.Fatalf("struct slice = %#v", dest.Tag)
	}
}

